package com.dropai.rewrite.service.ppt;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import java.nio.file.*;
import java.util.*;

/** Converts persisted, approved slide plans into the frozen renderer contract without generating content. */
@Service
public class PptProductionTreeAdapter {
    private final ObjectMapper mapper;public PptProductionTreeAdapter(ObjectMapper mapper){this.mapper=mapper;}
    public PptAssetMapperV1.MappingResult adapt(Map<String,Object> project,List<Map<String,Object>> sections,List<Map<String,Object>> slides,List<Map<String,Object>> assets){Map<String,Map<String,Object>> assetById=new LinkedHashMap<>();for(var a:assets)assetById.put(s(a.get("id")),a);List<PptAssetMapperV1.MappedSlideNode> out=new ArrayList<>();int n=1;var payload=new PptOutlineValidatorV1.FixedPayload(required(project,"topic"),required(project,"english_topic"),required(project,"presenter"),required(project,"major"),required(project,"advisor"),required(project,"student_number"));out.add(mapped(fixed(n++,"COVER",payload.title(),payload,List.of()),List.of()));List<PptOutlineValidatorV1.AgendaItem> agenda=new ArrayList<>();int start=3,index=0;for(var section:sections){String sid=s(section.get("id"));long count=slides.stream().filter(x->sid.equals(s(x.get("section_id")))).count();if(count>0){agenda.add(new PptOutlineValidatorV1.AgendaItem(++index,s(section.get("title")),"SECTION_"+index,List.of(start,start+(int)count-1)));start+=count;}}out.add(mapped(fixed(n++,"AGENDA","目录",null,agenda),List.of()));for(var slide:slides){String title=required(slide,"title");List<String> boxes=list(slide.get("body_boxes_json"));String description=s(slide.get("content_summary"));if(description.isBlank()&&!boxes.isEmpty())description=boxes.get(boxes.size()-1);final String summary=description;List<String> points=boxes.stream().filter(x->!x.equals(summary)).limit(3).toList();if(points.isEmpty())points=boxes.stream().limit(3).toList();String pageType="IMAGE".equalsIgnoreCase(s(slide.get("slide_type")))?"IMAGE":"CONTENT";String purpose=purpose(title,pageType);var refs=new PptContentPlannerV2.SourceRefs(s(slide.get("chapter_title")),List.of(),"",List.of(),List.of());List<PptAssetMapperV1.AssetBinding> bindings=new ArrayList<>();if("IMAGE".equals(pageType)){List<String> ids=list(slide.get("asset_ids_json"));if(ids.isEmpty())throw new IllegalStateException("图片页缺少素材绑定: "+title);String id=ids.get(0);Map<String,Object>a=assetById.get(id);if(a==null)throw new IllegalStateException("图片素材不存在: "+id);Path path=Path.of(s(a.get("file_path")));if(!Files.isRegularFile(path))throw new IllegalStateException("图片文件不存在: "+path);int w=i(a.get("width")),h=i(a.get("height"));double ratio=w>0&&h>0?(double)w/h:16d/9;bindings.add(new PptAssetMapperV1.AssetBinding(id,path.toAbsolutePath().normalize().toString(),"SCREENSHOT",w,h,ratio,ratio>=1.2?"LANDSCAPE":ratio<=.83?"PORTRAIT":"SQUARE",false,false,100,"PERSISTED_ASSET_ID"));refs=new PptContentPlannerV2.SourceRefs(s(slide.get("chapter_title")),List.of(),id,List.of(),List.of());}var page=new PptOutlineValidatorV1.FullSlideNode(n++,pageType,"CONTENT",title,purpose,"",points,description,s(slide.get("chapter_title")),null,null,List.of(),"IMAGE".equals(pageType)?"PROOF":"",refs,"IMAGE".equals(pageType),List.of(),1);out.add(mapped(page,bindings));}out.add(mapped(fixed(n,"THANKS","谢谢大家",payload,List.of()),List.of()));return new PptAssetMapperV1.MappingResult(true,false,"ASSET_MAPPED_TREE",out.size(),out,List.of());}
    private PptOutlineValidatorV1.FullSlideNode fixed(int n,String type,String title,PptOutlineValidatorV1.FixedPayload p,List<PptOutlineValidatorV1.AgendaItem>a){return new PptOutlineValidatorV1.FullSlideNode(n,type,type,title,"","",List.of(),"","",null,p,a,"",null,false,List.of(),1);}private PptAssetMapperV1.MappedSlideNode mapped(PptOutlineValidatorV1.FullSlideNode p,List<PptAssetMapperV1.AssetBinding>a){return new PptAssetMapperV1.MappedSlideNode(p,a);}private String required(Map<String,Object>m,String k){String v=s(m.get(k));if(v.isBlank())throw new IllegalStateException("PPT封面信息缺失: "+k);return v;}private String purpose(String t,String type){if("IMAGE".equals(type))return"RESULT";if(t.contains("测试"))return"TEST";if(t.contains("总结")||t.contains("展望"))return"SUMMARY";if(t.contains("设计")||t.contains("架构")||t.contains("数据库"))return"DESIGN";return"IMPLEMENTATION";}private List<String> list(Object v){try{Object x=v instanceof String str?mapper.readValue(str,Object.class):v;if(x instanceof List<?>l)return l.stream().map(this::s).filter(z->!z.isBlank()).toList();}catch(Exception ignored){}return List.of();}private String s(Object v){return v==null?"":String.valueOf(v).trim();}private int i(Object v){try{return v instanceof Number n?n.intValue():Integer.parseInt(s(v));}catch(Exception e){return 0;}}
}
